    #[test]
    fn sequential_code_input_preserves_spaces_and_literal_syntax() {
        let mut html = "<pre><code></code></pre><p>Keep me.</p>".to_owned();
        let mut literal = String::new();
        for input in ["let", " ", "value", " = ", "<b>", "&amp;", "</b>", "\n", "  ", "é界"] {
            let caret = CanonicalTextPoint::new("/pre[1]/code[1]", 0, literal.len());
            html = apply_canonical_patches(&html, &[CanonicalPatch::ReplaceVisibleText {
                start: caret.clone(), end: caret.clone(), replacement: input.to_owned(),
            }]).unwrap();
            literal.push_str(input);
            assert_eq!(canonical_text_run(&html, &caret).unwrap(), literal, "after {input:?}");
            assert_eq!(norm(&html), html);
            assert!(html.ends_with("<p>Keep me.</p>"));
        }
    }

